<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {supabase} from '../lib/supabase';const router=useRouter(),email=ref(''),password=ref(''),error=ref(''),busy=ref(false);async function login(){busy.value=true;error.value='';try{const {error:e}=await supabase.auth.signInWithPassword({email:email.value,password:password.value});if(e)throw e;await router.replace('/dashboard')}catch(e:any){error.value=e.message||'Sign in failed'}finally{busy.value=false}}</script>
<template><main class="min-h-screen grid place-items-center p-5"><form class="panel w-full max-w-md p-8 space-y-5" @submit.prevent="login"><div><p class="text-sm font-semibold text-indigo-600">HYBRID SHOP</p><h1 class="text-2xl font-bold mt-2">Sign in to your account</h1><p class="text-sm text-slate-500 mt-1">Use the account provided by your administrator.</p></div><p v-if="error" class="text-sm text-red-600">{{error}}</p><label class="block text-sm font-medium">Email address<input v-model="email" type="email" class="field mt-1" required autocomplete="username"></label><label class="block text-sm font-medium">Password<input v-model="password" type="password" class="field mt-1" required autocomplete="current-password"></label><button class="btn btn-primary w-full" :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button></form></main></template>
